    13	public final class ReservationRepository {
    14	    private static final String COLUMNS = """
    15	            id, room_number, guest_name, guest_email, guest_cpf, company_cnpj, company_name, guest_passport,
    16	            guest_country, check_in, check_out, guests, rate_plan, nights, subtotal, discount, total, status,
    17	            amount_paid, refund""";
    18	
    19	    private final Database db;
    20	
    21	    public ReservationRepository(Database db) {
    22	        this.db = db;
    23	    }
    24	
    25	    public Reservation insert(Reservation r) {
    26	        String sql = """
    27	                INSERT INTO reservations (room_number, guest_name, guest_email, guest_cpf, company_cnpj,
    28	                    company_name, guest_passport, guest_country, check_in, check_out, guests, rate_plan, nights,
    29	                    subtotal, discount, total, status, amount_paid, refund)
    30	                VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?) RETURNING id""";
    31	        long id = db.withConnection(c -> {
    32	            try (PreparedStatement ps = c.prepareStatement(sql)) {
    33	                IdentityFields f = r.identity().fields();
    34	                int i = 1;
    35	                ps.setInt(i++, r.room().number());
    36	                ps.setString(i++, r.guestName());
    37	                ps.setString(i++, r.guestEmail());
    38	                ps.setString(i++, f.guestCpf());
    39	                ps.setString(i++, f.companyCnpj());
    40	                ps.setString(i++, f.companyName());
    41	                ps.setString(i++, f.guestPassport());
    42	                ps.setString(i++, f.guestCountry());
    43	                ps.setObject(i++, r.checkIn());
    44	                ps.setObject(i++, r.checkOut());
    45	                ps.setInt(i++, r.guests());
    46	                ps.setString(i++, r.ratePlan().name());
    47	                ps.setInt(i++, r.nights());
    48	                ps.setBigDecimal(i++, r.subtotal());
    49	                ps.setBigDecimal(i++, r.discount());
    50	                ps.setBigDecimal(i++, r.total());
    51	                ps.setString(i++, r.status().name());
    52	                ps.setBigDecimal(i++, r.amountPaid());
    53	                ps.setBigDecimal(i, r.refund());
    54	                try (ResultSet rs = ps.executeQuery()) {
    55	                    rs.next();
    56	                    return rs.getLong(1);
    57	                }
    58	            }
    59	        });
    60	        r.assignId(id);
    61	        return r;
    62	    }
    63	
    64	    public void save(Reservation r) {
    65	        db.withConnection(c -> {
    66	            try (PreparedStatement ps = c.prepareStatement(
    67	                    "UPDATE reservations SET status=?, amount_paid=?, refund=? WHERE id=?")) {
    68	                ps.setString(1, r.status().name());
    69	                ps.setBigDecimal(2, r.amountPaid());
    70	                ps.setBigDecimal(3, r.refund());
    71	                ps.setLong(4, r.id());
    72	                return ps.executeUpdate();
    73	            }
    74	        });
    75	    }
    76	
    77	    public Optional<Reservation> find(long id) {
    78	        return query("SELECT " + COLUMNS + " FROM reservations WHERE id=?", ps -> ps.setLong(1, id))
    79	                .stream().findFirst();
    80	    }
    81	
    82	    /** Alguma reserva não cancelada do quarto toca alguma das noites [checkIn, checkOut)? */
    83	    public boolean hasOverlap(int roomNumber, LocalDate checkIn, LocalDate checkOut) {
    84	        return db.withConnection(c -> {
    85	            try (PreparedStatement ps = c.prepareStatement("""
    86	                    SELECT 1 FROM reservations
    87	                    WHERE room_number=? AND status <> 'CANCELLED' AND check_in < ? AND check_out > ?
    88	                    LIMIT 1""")) {
    89	                ps.setInt(1, roomNumber);
    90	                ps.setObject(2, checkOut);
    91	                ps.setObject(3, checkIn);
    92	                try (ResultSet rs = ps.executeQuery()) {
    93	                    return rs.next();
    94	                }
    95	            }
    96	        });
    97	    }
    98	
    99	    /** Reservas que têm a noite entre a entrada (inclusive) e a saída (exclusive). */
   100	    public List<Reservation> findCoveringNight(LocalDate night) {
   101	        return query("SELECT " + COLUMNS + " FROM reservations WHERE check_in <= ? AND check_out > ? ORDER BY id",
   102	                ps -> {
   103	                    ps.setObject(1, night);
   104	                    ps.setObject(2, night);
   105	                });
   106	    }
   107	
   108	    /** Reservas com entrada em [from, to), por data de entrada e depois número. */
   109	    public List<Reservation> findCheckingInBetween(LocalDate from, LocalDate to) {
   110	        return query("SELECT " + COLUMNS
   111	                + " FROM reservations WHERE check_in >= ? AND check_in < ? ORDER BY check_in, id", ps -> {
   112	            ps.setObject(1, from);
   113	            ps.setObject(2, to);
   114	        });
   115	    }
   116	
   117	    @FunctionalInterface
   118	    private interface Binder {
   119	        void bind(PreparedStatement ps) throws SQLException;
   120	    }
   121	
   122	    private List<Reservation> query(String sql, Binder binder) {
   123	        return db.withConnection(c -> {
   124	            try (PreparedStatement ps = c.prepareStatement(sql)) {
   125	                binder.bind(ps);
   126	                try (ResultSet rs = ps.executeQuery()) {
   127	                    List<Reservation> list = new ArrayList<>();
   128	                    while (rs.next()) {
   129	                        list.add(map(rs));
   130	                    }
   131	                    return list;
   132	                }
   133	            }
   134	        });
   135	    }
   136	
   137	    private Reservation map(ResultSet rs) throws SQLException {
   138	        IdentityFields fields = new IdentityFields(rs.getString("guest_cpf"), rs.getString("company_cnpj"),
   139	                rs.getString("company_name"), rs.getString("guest_passport"), rs.getString("guest_country"));
   140	        return new Reservation(
   141	                rs.getLong("id"),
   142	                RoomCatalog.find(rs.getInt("room_number")).orElseThrow(),
   143	                rs.getString("guest_name"),
   144	                rs.getString("guest_email"),
   145	                IdentityKinds.from(fields),
   146	                rs.getObject("check_in", LocalDate.class),
   147	                rs.getObject("check_out", LocalDate.class),
   148	                rs.getInt("guests"),
   149	                RatePlan.valueOf(rs.getString("rate_plan")),
   150	                rs.getInt("nights"),
   151	                rs.getBigDecimal("subtotal"),
   152	                rs.getBigDecimal("discount"),
   153	                rs.getBigDecimal("total"),
   154	                ReservationStatus.valueOf(rs.getString("status")),
   155	                rs.getBigDecimal("amount_paid"),
   156	                rs.getBigDecimal("refund"));
   157	    }
   158	}
