    21	    public Api(ReservationService reservations, ReportService reports) {
    22	        this.reservations = reservations;
    23	        this.reports = reports;
    24	    }
    25	
    26	    public Javalin create() {
    27	        Javalin app = Javalin.create();
    28	        app.get("/rooms", ctx -> json(ctx, 200, RoomCatalog.all().stream().map(Views.RoomView::of).toList()));
    29	        app.post("/reservations", ctx -> json(ctx, 201,
    30	                Views.ReservationView.of(reservations.create(reader.newReservation(ctx.body())))));
    31	        app.get("/reservations/{id}", ctx -> reservation(ctx, reservations::get));
    32	        app.post("/reservations/{id}/confirmation", ctx -> reservation(ctx, reservations::confirm));
    33	        app.post("/reservations/{id}/cancellation", ctx -> reservation(ctx, reservations::cancel));
    34	        app.post("/reservations/{id}/check-in", ctx -> reservation(ctx, reservations::checkIn));
    35	        app.post("/reservations/{id}/check-out", ctx -> document(ctx, reservations::checkOut));
    36	        app.get("/reservations/{id}/document", ctx -> document(ctx, reservations::document));
    37	        app.get("/messages", ctx -> json(ctx, 200, reservations.sentMessages().stream().map(Views.MessageView::of).toList()));
    38	        app.get("/reports/occupancy", ctx ->
    39	                csv(ctx, reports.occupancy(reader.night(ctx.queryParam("date")))));
    40	        app.get("/reports/revenue", ctx ->
    41	                csv(ctx, reports.revenue(reader.month(ctx.queryParam("month")))));
    42	
    43	        app.exception(DomainException.class, (e, ctx) ->
    44	                json(ctx, e.code().httpStatus(), new Views.ErrorView(e.code().name(), e.getMessage())));
    45	        app.exception(Exception.class, (e, ctx) -> {
    46	            LOG.error("Erro inesperado", e);
    47	            json(ctx, 500, new Views.ErrorView("INTERNAL_ERROR", "Erro interno"));
    48	        });
    49	        return app;
    50	    }
    51	
    52	    private void reservation(Context ctx, LongFunction<Reservation> operation) {
    53	        json(ctx, 200, Views.ReservationView.of(operation.apply(reservationId(ctx))));
    54	    }
