197	    63	    /** Cria o que o sistema precisa; espera o banco ficar disponível. */
198	    64	    public void initSchema() {
199	    65	        SQLException last = null;
200	    66	        for (int attempt = 0; attempt < 60; attempt++) {
201	    67	            try (Connection c = dataSource.getConnection(); Statement s = c.createStatement()) {
202	    68	                s.execute(SCHEMA);
203	    69	                return;
204	    70	            } catch (SQLException e) {
205	    71	                last = e;
206	    72	                try {
207	    73	                    Thread.sleep(1000);
208	    74	                } catch (InterruptedException ie) {
209	    75	                    Thread.currentThread().interrupt();
210	    76	                    break;
211	    77	                }
212	    78	            }
213	    79	        }
214	    80	        throw new IllegalStateException("Banco indisponível", last);
215	    81	    }
