217	    83	    public <R> R withConnection(SqlFunction<Connection, R> work) {
218	    84	        Connection existing = current.get();
219	    85	        try {
220	    86	            if (existing != null) {
221	    87	                return work.apply(existing);
222	    88	            }
223	    89	            try (Connection c = dataSource.getConnection()) {
224	    90	                return work.apply(c);
225	    91	            }
226	    92	        } catch (SQLException e) {
227	    93	            throw new IllegalStateException(e);
228	    94	        }
229	    95	    }
230	    96	
231	    97	    /** Tudo o que os repositórios fizerem dentro de {@code work} vale junto ou não vale. */
232	    98	    public <R> R inTransaction(Supplier<R> work) {
233	    99	        if (current.get() != null) {
234	   100	            return work.get();
235	   101	        }
236	   102	        try (Connection c = dataSource.getConnection()) {
237	   103	            c.setAutoCommit(false);
238	   104	            current.set(c);
239	   105	            try {
240	   106	                R result = work.get();
241	   107	                c.commit();
242	   108	                return result;
243	   109	            } catch (RuntimeException e) {
244	   110	                c.rollback();
245	   111	                throw e;
246	   112	            } finally {
247	   113	                current.remove();
248	   114	            }
249	   115	        } catch (SQLException e) {
250	   116	            throw new IllegalStateException(e);
251	   117	        }
252	   118	    }
253	   119	
254	   120	    public void close() {
255	   121	        dataSource.close();
256	   122	    }
