    10	
    11	public final class Database {
    12	    @FunctionalInterface
    13	    public interface SqlFunction<T, R> {
    14	        R apply(T value) throws SQLException;
    15	    }
    16	
    17	    private static final String SCHEMA = """
    18	            CREATE TABLE IF NOT EXISTS reservations (
    19	                id BIGSERIAL PRIMARY KEY,
    20	                room_number INT NOT NULL,
    21	                guest_name TEXT NOT NULL,
    22	                guest_email TEXT NOT NULL,
    23	                guest_cpf TEXT,
    24	                company_cnpj TEXT,
    25	                company_name TEXT,
    26	                guest_passport TEXT,
    27	                guest_country TEXT,
    28	                check_in DATE NOT NULL,
    29	                check_out DATE NOT NULL,
    30	                guests INT NOT NULL,
    31	                rate_plan TEXT NOT NULL,
    32	                nights INT NOT NULL,
    33	                subtotal NUMERIC(12,2) NOT NULL,
    34	                discount NUMERIC(12,2) NOT NULL,
    35	                total NUMERIC(12,2) NOT NULL,
    36	                status TEXT NOT NULL,
    37	                amount_paid NUMERIC(12,2) NOT NULL,
    38	                refund NUMERIC(12,2)
    39	            );
    40	            CREATE INDEX IF NOT EXISTS reservations_room_idx ON reservations (room_number, check_in);
    41	            CREATE TABLE IF NOT EXISTS messages (
    42	                id BIGSERIAL PRIMARY KEY,
    43	                channel TEXT NOT NULL,
    44	                recipient TEXT NOT NULL,
    45	                subject TEXT NOT NULL,
    46	                body TEXT NOT NULL
    47	            );
    48	            """;
    49	
    50	    private final HikariDataSource dataSource;
    51	    private final ThreadLocal<Connection> current = new ThreadLocal<>();
    52	
    53	    public Database(String url, String user, String password) {
    54	        HikariConfig config = new HikariConfig();
    55	        config.setJdbcUrl(url);
    56	        config.setUsername(user);
    57	        config.setPassword(password);
    58	        config.setMaximumPoolSize(8);
    59	        config.setInitializationFailTimeout(-1);
    60	        this.dataSource = new HikariDataSource(config);
    61	    }
    62	
    63	    /** Cria o que o sistema precisa; espera o banco ficar disponível. */
    64	    public void initSchema() {
    65	        SQLException last = null;
    66	        for (int attempt = 0; attempt < 60; attempt++) {
    67	            try (Connection c = dataSource.getConnection(); Statement s = c.createStatement()) {
    68	                s.execute(SCHEMA);
    69	                return;
    70	            } catch (SQLException e) {
    71	                last = e;
    72	                try {
    73	                    Thread.sleep(1000);
    74	                } catch (InterruptedException ie) {
    75	                    Thread.currentThread().interrupt();
    76	                    break;
    77	                }
    78	            }
    79	        }
    80	        throw new IllegalStateException("Banco indisponível", last);
    81	    }
    82	
    83	    public <R> R withConnection(SqlFunction<Connection, R> work) {
    84	        Connection existing = current.get();
    85	        try {
    86	            if (existing != null) {
    87	                return work.apply(existing);
    88	            }
    89	            try (Connection c = dataSource.getConnection()) {
    90	                return work.apply(c);
    91	            }
    92	        } catch (SQLException e) {
    93	            throw new IllegalStateException(e);
    94	        }
    95	    }
    96	
    97	    /** Tudo o que os repositórios fizerem dentro de {@code work} vale junto ou não vale. */
    98	    public <R> R inTransaction(Supplier<R> work) {
    99	        if (current.get() != null) {
   100	            return work.get();
   101	        }
   102	        try (Connection c = dataSource.getConnection()) {
   103	            c.setAutoCommit(false);
   104	            current.set(c);
   105	            try {
   106	                R result = work.get();
   107	                c.commit();
   108	                return result;
   109	            } catch (RuntimeException e) {
   110	                c.rollback();
   111	                throw e;
   112	            } finally {
   113	                current.remove();
   114	            }
   115	        } catch (SQLException e) {
   116	            throw new IllegalStateException(e);
   117	        }
   118	    }
   119	
   120	    public void close() {
   121	        dataSource.close();
   122	    }
   123	}
