    82	    /** Alguma reserva não cancelada do quarto toca alguma das noites [checkIn, checkOut)? */
    83	    public boolean hasOverlap(int roomNumber, LocalDate checkIn, LocalDate checkOut) {
    84	        return db.withConnection(c -> {
    85	            try (PreparedStatement ps = c.prepareStatement("""
    86	                    SELECT 1 FROM reservations
    87	                    WHERE room_number=? AND status <> 'CANCELLED' AND check_in < ? AND check_out > ?
    88	                    LIMIT 1""")) {
    89	                ps.setInt(1, roomNumber);
    90	                ps.setObject(2, checkOut);
    91	                ps.setObject(3, checkIn);
    92	                try (ResultSet rs = ps.executeQuery()) {
    93	                    return rs.next();
    94	                }
    95	            }
    96	        });
    97	    }
    98	
    99	    /** Reservas que têm a noite entre a entrada (inclusive) e a saída (exclusive). */
   100	    public List<Reservation> findCoveringNight(LocalDate night) {
   101	        return query("SELECT " + COLUMNS + " FROM reservations WHERE check_in <= ? AND check_out > ? ORDER BY id",
   102	                ps -> {
   103	                    ps.setObject(1, night);
   104	                    ps.setObject(2, night);
   105	                });
   106	    }
   107	
   108	    /** Reservas com entrada em [from, to), por data de entrada e depois número. */
   109	    public List<Reservation> findCheckingInBetween(LocalDate from, LocalDate to) {
   110	        return query("SELECT " + COLUMNS
   111	                + " FROM reservations WHERE check_in >= ? AND check_in < ? ORDER BY check_in, id", ps -> {
   112	            ps.setObject(1, from);
   113	            ps.setObject(2, to);
   114	        });
   115	    }
   116	
   117	    @FunctionalInterface
   118	    private interface Binder {
   119	        void bind(PreparedStatement ps) throws SQLException;
   120	    }
   121	
   122	    private List<Reservation> query(String sql, Binder binder) {
   123	        return db.withConnection(c -> {
   124	            try (PreparedStatement ps = c.prepareStatement(sql)) {
   125	                binder.bind(ps);
   126	                try (ResultSet rs = ps.executeQuery()) {
   127	                    List<Reservation> list = new ArrayList<>();
   128	                    while (rs.next()) {
   129	                        list.add(map(rs));
   130	                    }
   131	                    return list;
   132	                }
   133	            }
   134	        });
   135	    }
   136	
   137	    private Reservation map(ResultSet rs) throws SQLException {
   138	        IdentityFields fields = new IdentityFields(rs.getString("guest_cpf"), rs.getString("company_cnpj"),
   139	                rs.getString("company_name"), rs.getString("guest_passport"), rs.getString("guest_country"));
   140	        return new Reservation(
   141	                rs.getLong("id"),
   142	                RoomCatalog.find(rs.getInt("room_number")).orElseThrow(),
   143	                rs.getString("guest_name"),
   144	                rs.getString("guest_email"),
   145	                IdentityKinds.from(fields),
   146	                rs.getObject("check_in", LocalDate.class),
   147	                rs.getObject("check_out", LocalDate.class),
   148	                rs.getInt("guests"),
   149	                RatePlan.valueOf(rs.getString("rate_plan")),
   150	                rs.getInt("nights"),
   151	                rs.getBigDecimal("subtotal"),
   152	                rs.getBigDecimal("discount"),
   153	                rs.getBigDecimal("total"),
   154	                ReservationStatus.valueOf(rs.getString("status")),
   155	                rs.getBigDecimal("amount_paid"),
   156	                rs.getBigDecimal("refund"));
   157	    }
   158	}
