     1	package br.com.marealta.web;
     2	
     3	import br.com.marealta.domain.*;
     4	import com.fasterxml.jackson.core.JsonProcessingException;
     5	import com.fasterxml.jackson.databind.JsonNode;
     6	import com.fasterxml.jackson.databind.ObjectMapper;
     7	
     8	import java.time.LocalDate;
     9	import java.time.YearMonth;
    10	import java.time.format.DateTimeParseException;
    11	import java.util.regex.Pattern;
    12	
    13	/** Lê e valida o que chega do site; qualquer problema vira INVALID_REQUEST. */
    14	final class RequestReader {
    15	    private static final Pattern MONTH = Pattern.compile("\\d{4}-(0[1-9]|1[0-2])");
    16	
    17	    private final ObjectMapper mapper;
    18	
    19	    RequestReader(ObjectMapper mapper) {
    20	        this.mapper = mapper;
    21	    }
    22	
    23	    NewReservation newReservation(String body) {
    24	        JsonNode json = parseObject(body);
    25	        LocalDate checkIn = date(requiredText(json, "checkIn"), "checkIn");
    26	        LocalDate checkOut = date(requiredText(json, "checkOut"), "checkOut");
    27	        if (!checkOut.isAfter(checkIn)) {
    28	            throw DomainException.invalid("A saída deve ser depois da entrada");
    29	        }
    30	        int guests = integer(json, "guests");
    31	        if (guests < 1) {
    32	            throw DomainException.invalid("É preciso pelo menos um hóspede");
    33	        }
    34	        IdentityFields fields = new IdentityFields(optionalText(json, "guestCpf"), optionalText(json, "companyCnpj"),
    35	                optionalText(json, "companyName"), optionalText(json, "guestPassport"),
    36	                optionalText(json, "guestCountry"));
    37	        return new NewReservation(integer(json, "roomNumber"), requiredText(json, "guestName"),
    38	                requiredText(json, "guestEmail"), IdentityKinds.from(fields), checkIn, checkOut, guests,
    39	                ratePlan(requiredText(json, "ratePlan")));
    40	    }
    41	
    42	    LocalDate night(String value) {
    43	        return date(value, "date");
    44	    }
    45	
    46	    YearMonth month(String value) {
    47	        if (value == null || !MONTH.matcher(value).matches()) {
    48	            throw DomainException.invalid("Mês inválido, use o formato 2027-07");
    49	        }
    50	        return YearMonth.parse(value);
    51	    }
    52	
    53	    private JsonNode parseObject(String body) {
    54	        try {
    55	            JsonNode node = mapper.readTree(body);
    56	            if (node == null || !node.isObject()) {
    57	                throw DomainException.invalid("O corpo deve ser um objeto JSON");
    58	            }
    59	            return node;
    60	        } catch (JsonProcessingException e) {
    61	            throw DomainException.invalid("O corpo não é um JSON válido");
    62	        }
    63	    }
    64	
    65	    private static String optionalText(JsonNode json, String name) {
    66	        JsonNode value = json.get(name);
    67	        if (value == null || value.isNull()) {
    68	            return null;
    69	        }
    70	        if (!value.isTextual()) {
    71	            throw DomainException.invalid("Campo deve ser texto: " + name);
    72	        }
    73	        return value.asText();
    74	    }
    75	
    76	    private static String requiredText(JsonNode json, String name) {
    77	        return IdentityKind.require(optionalText(json, name), name);
    78	    }
    79	
    80	    private static int integer(JsonNode json, String name) {
    81	        JsonNode value = json.get(name);
    82	        if (value == null || !value.isIntegralNumber() || !value.canConvertToInt()) {
    83	            throw DomainException.invalid("Campo deve ser um número inteiro: " + name);
    84	        }
    85	        return value.asInt();
    86	    }
    87	
    88	    private static LocalDate date(String value, String name) {
    89	        try {
    90	            return LocalDate.parse(value == null ? "" : value);
    91	        } catch (DateTimeParseException e) {
    92	            throw DomainException.invalid("Data inválida em " + name + ", use o formato 2027-07-10");
    93	        }
    94	    }
    95	
    96	    private static RatePlan ratePlan(String value) {
    97	        try {
    98	            return RatePlan.valueOf(value);
    99	        } catch (IllegalArgumentException e) {
   100	            throw DomainException.invalid("Plano de tarifa inválido: " + value);
   101	        }
   102	    }
   103	}
