    45	
    46	    /** Nova reserva pendente, com os valores já calculados. */
    47	    public static Reservation book(Room room, String guestName, String guestEmail, GuestIdentity identity,
    48	                                   LocalDate checkIn, LocalDate checkOut, int guests, RatePlan ratePlan) {
    49	        Pricing.Quote quote = Pricing.quote(room.type(), checkIn, checkOut, ratePlan);
    50	        return new Reservation(0, room, guestName, guestEmail, identity, checkIn, checkOut, guests, ratePlan,
    51	                quote.nights(), quote.subtotal(), quote.discount(), quote.total(),
    52	                ReservationStatus.PENDING, Money.ZERO, null);
    53	    }
    54	
    55	    public void confirm() {
    56	        moveTo(ReservationStatus.CONFIRMED);
    57	        amountPaid = total;
    58	    }
    59	
    60	    public void cancel() {
    61	        moveTo(ReservationStatus.CANCELLED);
    62	        refund = ratePlan.refundOf(amountPaid);
