     1	package br.com.marealta.domain;
     2	
     3	import java.math.BigDecimal;
     4	import java.time.LocalDate;
     5	import java.time.Month;
     6	
     7	public final class Pricing {
     8	    private static final BigDecimal HIGH_SEASON_FACTOR = new BigDecimal("1.20");
     9	
    10	    public record Quote(int nights, BigDecimal subtotal, BigDecimal discount, BigDecimal total) {
    11	    }
    12	
    13	    private Pricing() {
    14	    }
    15	
    16	    public static boolean isHighSeason(LocalDate night) {
    17	        Month month = night.getMonth();
    18	        return month == Month.JANUARY || month == Month.FEBRUARY || month == Month.JULY
    19	                || (month == Month.DECEMBER && night.getDayOfMonth() >= 15);
    20	    }
    21	
    22	    public static BigDecimal nightPrice(RoomType type, LocalDate night) {
    23	        BigDecimal rate = type.nightlyRate();
    24	        return isHighSeason(night) ? Money.round(rate.multiply(HIGH_SEASON_FACTOR)) : rate;
    25	    }
    26	
    27	    public static Quote quote(RoomType type, LocalDate checkIn, LocalDate checkOut, RatePlan plan) {
    28	        BigDecimal subtotal = Money.ZERO;
    29	        int nights = 0;
    30	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
    31	            subtotal = Money.round(subtotal.add(nightPrice(type, night)));
    32	            nights++;
    33	        }
    34	        BigDecimal discount = plan.discountOn(subtotal);
    35	        return new Quote(nights, subtotal, discount, Money.round(subtotal.subtract(discount)));
    36	    }
    37	}
