    10	public class ReservationService {
    11	    private final Database db;
    12	    private final ReservationRepository reservations;
    13	    private final MessageRepository messages;
    14	
    15	    public ReservationService(Database db, ReservationRepository reservations, MessageRepository messages) {
    16	        this.db = db;
    17	        this.reservations = reservations;
    18	        this.messages = messages;
    19	    }
    20	
    21	    public synchronized Reservation create(NewReservation request) {
    22	        Room room = RoomCatalog.find(request.roomNumber())
    23	                .orElseThrow(() -> new DomainException(ErrorCode.ROOM_NOT_FOUND, "Quarto inexistente"));
    24	        if (request.guests() > room.capacity()) {
    25	            throw new DomainException(ErrorCode.CAPACITY_EXCEEDED,
    26	                    "O quarto comporta no máximo " + room.capacity() + " hóspedes");
    27	        }
    28	        return db.inTransaction(() -> {
    29	            if (reservations.hasOverlap(room.number(), request.checkIn(), request.checkOut())) {
    30	                throw new DomainException(ErrorCode.ROOM_UNAVAILABLE, "Quarto já reservado em alguma das noites");
    31	            }
    32	            return reservations.insert(Reservation.book(room, request.guestName(), request.guestEmail(),
    33	                    request.identity(), request.checkIn(), request.checkOut(), request.guests(),
    34	                    request.ratePlan()));
    35	        });
    36	    }
    37	
    38	    public Reservation get(long id) {
    39	        return reservations.find(id).orElseThrow(
    40	                () -> new DomainException(ErrorCode.RESERVATION_NOT_FOUND, "Reserva inexistente"));
    41	    }
    42	
    43	    public synchronized Reservation confirm(long id) {
    44	        return change(id, Reservation::confirm, r -> messages.add(ConfirmationEmail.compose(r)));
    45	    }
    46	
    47	    public synchronized Reservation cancel(long id) {
    48	        return change(id, Reservation::cancel, r -> { });
    49	    }
    50	
    51	    public synchronized Reservation checkIn(long id) {
    52	        return change(id, Reservation::registerCheckIn, r -> { });
    53	    }
    54	
    55	    public synchronized ReservationDocument checkOut(long id) {
    56	        return change(id, Reservation::registerCheckOut, r -> { }).document();
    57	    }
    58	
    59	    public ReservationDocument document(long id) {
    60	        return get(id).document();
    61	    }
    62	
    63	    public List<Message> sentMessages() {
    64	        return messages.findAll();
    65	    }
    66	
    67	    /** A mudança de situação e o que vem junto dela valem juntos ou não valem. */
    68	    private Reservation change(long id, Consumer<Reservation> operation, Consumer<Reservation> sideEffect) {
    69	        return db.inTransaction(() -> {
    70	            Reservation r = get(id);
    71	            operation.accept(r);
    72	            reservations.save(r);
    73	            sideEffect.accept(r);
    74	            return r;
    75	        });
    76	    }
    77	}
